From 899d564d93124d8e13a285eccc289750aba489e4 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 04:00:45 +0100
Subject: [PATCH] applet: say "Share" instead of "Connect" for hotspot
 connections

Saved Wi-Fi connections in access point mode start a hotspot when they
are activated, but the widget labelled their button "Connect" just like
for normal networks. Expose whether an item is a hotspot and use "Share".

BUG: 423410
---
 applet/ConnectionItem.qml        | 7 ++++++-
 libs/models/networkmodel.cpp     | 3 +++
 libs/models/networkmodel.h       | 1 +
 libs/models/networkmodelitem.cpp | 1 +
 4 files changed, 11 insertions(+), 1 deletion(-)

diff --git a/applet/ConnectionItem.qml b/applet/ConnectionItem.qml
index e2a79fd2f..4f83fabda 100644
--- a/applet/ConnectionItem.qml
+++ b/applet/ConnectionItem.qml
@@ -61,7 +61,12 @@ PlasmaExtras.ExpandableListItem {
         }

         icon.name: isDeactivated ? "network-connect-symbolic" : "network-disconnect-symbolic"
-        text: isDeactivated ? i18n("Connect") : i18n("Disconnect")
+        text: {
+            if (!isDeactivated) {
+                return i18n("Disconnect");
+            }
+            return connectionItem.model.IsHotspot ? i18nc("@action:button start sharing a hotspot connection", "Share") : i18n("Connect");
+        }
         onTriggered: {
             connectionItem.changeState()
             listView.newIndexSelected(index)
diff --git a/libs/models/networkmodel.cpp b/libs/models/networkmodel.cpp
index 0aec0317b..5a6436486 100644
--- a/libs/models/networkmodel.cpp
+++ b/libs/models/networkmodel.cpp
@@ -94,6 +94,8 @@ QVariant NetworkModel::data(const QModelIndex &index, int role) const
             return item->rxBytes();
         case TxBytesRole:
             return item->txBytes();
+        case IsHotspotRole:
+            return item->type() == NetworkManager::ConnectionSettings::Wireless && item->mode() == NetworkManager::WirelessSetting::Ap;
         case DelayModelUpdatesRole:
             return item->delayModelUpdates();
         case Qt::AccessibleDescriptionRole:
@@ -159,6 +161,7 @@ QHash<int, QByteArray> NetworkModel::roleNames() const
     roles[VpnType] = "VpnType";
     roles[RxBytesRole] = "RxBytes";
     roles[TxBytesRole] = "TxBytes";
+    roles[IsHotspotRole] = "IsHotspot";
     roles[DelayModelUpdatesRole] = "DelayModelUpdates";

     return roles;
diff --git a/libs/models/networkmodel.h b/libs/models/networkmodel.h
index 171cca36f..3cbfaee1e 100644
--- a/libs/models/networkmodel.h
+++ b/libs/models/networkmodel.h
@@ -64,6 +64,7 @@ public:
         VpnType,
         RxBytesRole,
         TxBytesRole,
+        IsHotspotRole,
         // writable roles
         DelayModelUpdatesRole,
     };
diff --git a/libs/models/networkmodelitem.cpp b/libs/models/networkmodelitem.cpp
index 70d48fb6a..44ceb66b2 100644
--- a/libs/models/networkmodelitem.cpp
+++ b/libs/models/networkmodelitem.cpp
@@ -311,6 +311,7 @@ void NetworkModelItem::setMode(const NetworkManager::WirelessSetting::NetworkMod
 {
     if (m_mode != mode) {
         m_mode = mode;
+        m_changedRoles << NetworkModel::IsHotspotRole;
         refreshIcon();
     }
 }
